<?php\n/**\n * ══════════════════════════════════════════════════════════════\n * SCRIPT DE INICIALIZAÇÃO DO BANCO DE DADOS\n * ══════════════════════════════════════════════════════════════\n * Execute este arquivo UMA VEZ: http://localhost/prefeitura/setup.php\n */\n\nrequire_once 'config.php';\n\ntry {\n    // Criar tabela de notícias\n    $pdo->exec(\"\n        CREATE TABLE IF NOT EXISTS noticias (\n            id INT PRIMARY KEY AUTO_INCREMENT,\n            titulo VARCHAR(255) NOT NULL,\n            categoria VARCHAR(100),\n            data DATE NOT NULL,\n            status ENUM('publicada', 'rascunho', 'arquivada') DEFAULT 'publicada',\n            resumo LONGTEXT,\n            autor VARCHAR(100),\n            imagem LONGBLOB,\n            criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n            atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n            INDEX(data),\n            INDEX(status)\n        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n    \");\n\n    // Criar tabela de licitações\n    $pdo->exec(\"\n        CREATE TABLE IF NOT EXISTS licitacoes (\n            id INT PRIMARY KEY AUTO_INCREMENT,\n            numero VARCHAR(50) NOT NULL UNIQUE,\n            objeto TEXT NOT NULL,\n            modalidade VARCHAR(100),\n            valor VARCHAR(50),\n            abertura DATE,\n            fase VARCHAR(100),\n            status ENUM('aberto', 'julgamento', 'homologado', 'concluido', 'cancelado') DEFAULT 'aberto',\n            edital LONGBLOB,\n            criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n            atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n            INDEX(numero),\n            INDEX(status),\n            INDEX(abertura)\n        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n    \");\n\n    // Criar tabela de diárias\n    $pdo->exec(\"\n        CREATE TABLE IF NOT EXISTS diarias (\n            id INT PRIMARY KEY AUTO_INCREMENT,\n            beneficiario VARCHAR(255) NOT NULL,\n            cargo VARCHAR(100),\n            destino VARCHAR(255),\n            periodo VARCHAR(100),\n            diarias INT,\n            valor VARCHAR(50),\n            status ENUM('publicada', 'pendente', 'rejeitada') DEFAULT 'publicada',\n            criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n            atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n            INDEX(beneficiario),\n            INDEX(status)\n        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n    \");\n\n    // Criar tabela de obras\n    $pdo->exec(\"\n        CREATE TABLE IF NOT EXISTS obras (\n            id INT PRIMARY KEY AUTO_INCREMENT,\n            nome VARCHAR(255) NOT NULL,\n            secretaria VARCHAR(100),\n            valor VARCHAR(50),\n            inicio DATE,\n            progresso INT DEFAULT 0,\n            status ENUM('planejada', 'andamento', 'concluida', 'paralisada') DEFAULT 'andamento',\n            descricao LONGTEXT,\n            criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n            atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n            INDEX(status),\n            INDEX(secretaria)\n        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n    \");\n\n    // Criar tabela de secretarias\n    $pdo->exec(\"\n        CREATE TABLE IF NOT EXISTS secretarias (\n            id INT PRIMARY KEY AUTO_INCREMENT,\n            nome VARCHAR(255) NOT NULL UNIQUE,\n            responsavel VARCHAR(255),\n            endereco TEXT,\n            telefone VARCHAR(20),\n            email VARCHAR(100),\n            horario VARCHAR(100),\n            competencias LONGTEXT,\n            criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n            atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n            INDEX(nome)\n        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n    \");\n\n    // Criar tabela de FAQ\n    $pdo->exec(\"\n        CREATE TABLE IF NOT EXISTS faq (\n            id INT PRIMARY KEY AUTO_INCREMENT,\n            pergunta TEXT NOT NULL,\n            resposta LONGTEXT,\n            ordem INT DEFAULT 0,\n            ativo BOOLEAN DEFAULT 1,\n            criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n            atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n            INDEX(ordem),\n            INDEX(ativo)\n        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n    \");\n\n    // Criar tabela de configurações\n    $pdo->exec(\"\n        CREATE TABLE IF NOT EXISTS configuracoes (\n            id INT PRIMARY KEY AUTO_INCREMENT,\n            chave VARCHAR(100) NOT NULL UNIQUE,\n            valor LONGTEXT,\n            tipo VARCHAR(50),\n            criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n            atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n            INDEX(chave)\n        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n    \");\n\n    // Inserir configurações iniciais\n    $configs = [\n        'nome_prefeitura' => 'Vargem Grande do Rio Pardo',\n        'estado' => 'Minas Gerais',\n        'telefone' => '(38) 3847-1200',\n        'email' => 'prefeitura@vargemgrande.mg.gov.br',\n        'endereco' => 'Praça XV de Novembro, s/n — Centro',\n        'cep' => '39.454-000',\n        'cnpj' => '19.851.397/0001-39'\n    ];\n\n    foreach ($configs as $chave => $valor) {\n        $pdo->prepare(\n            \"INSERT IGNORE INTO configuracoes (chave, valor, tipo) VALUES (?, ?, 'string')\"\n        )->execute([$chave, $valor]);\n    }\n\n    // Inserir secretarias iniciais\n    $secretarias = [\n        ['Gabinete do Prefeito', 'Prefeito Municipal', 'Praça XV de Novembro, s/n - Centro', '(38) 3847-1200', 'gabinete@vargemgrande.mg.gov.br'],\n        ['Secretaria de Saúde', 'Secretário de Saúde', 'Rua da Saúde, 100', '(38) 3847-1210', 'saude@vargemgrande.mg.gov.br'],\n        ['Secretaria de Educação', 'Secretário de Educação', 'Rua da Educação, 50', '(38) 3847-1220', 'educacao@vargemgrande.mg.gov.br'],\n        ['Secretaria de Obras', 'Secretário de Obras', 'Rua das Obras, 200', '(38) 3847-1230', 'obras@vargemgrande.mg.gov.br'],\n        ['Secretaria de Finanças', 'Secretário de Finanças', 'Rua das Finanças, 150', '(38) 3847-1240', 'financas@vargemgrande.mg.gov.br'],\n        ['Secretaria de Administração', 'Secretário de Administração', 'Rua da Administração, 100', '(38) 3847-1250', 'adm@vargemgrande.mg.gov.br'],\n    ];\n\n    $stmt = $pdo->prepare(\n        \"INSERT IGNORE INTO secretarias (nome, responsavel, endereco, telefone, email, horario, competencias) \n         VALUES (?, ?, ?, ?, ?, '08h - 17h', 'Gestão municipal')\"\n    );\n\n    foreach ($secretarias as $sec) {\n        $stmt->execute($sec);\n    }\n\n    echo \"<div style='font-family: Arial; padding: 20px; background: #d1fae5; border: 2px solid #2ecc40; border-radius: 8px;'>\n        <h2 style='color: #065f46;'>✅ Banco de dados criado com sucesso!</h2>\n        <p style='color: #047857;'><strong>Tabelas criadas:</strong></p>\n        <ul style='color: #047857;'>\n            <li>noticias</li>\n            <li>licitacoes</li>\n            <li>diarias</li>\n            <li>obras</li>\n            <li>secretarias</li>\n            <li>faq</li>\n            <li>configuracoes</li>\n        </ul>\n        <p style='margin-top: 20px; color: #047857;'><strong>⚠️ Próximos passos:</strong></p>\n        <ol style='color: #047857;'>\n            <li>Delete este arquivo (setup.php) do servidor por segurança</li>\n            <li>Configure suas credenciais MySQL em <strong>config.php</strong></li>\n            <li>Acesse <strong>index.html</strong> para verificar se tudo está funcionando</li>\n        </ol>\n    </div>\";\n\n} catch (Exception $e) {\n    echo \"<div style='font-family: Arial; padding: 20px; background: #fee2e2; border: 2px solid #f85149; border-radius: 8px;'>\n        <h2 style='color: #991b1b;'>❌ Erro ao criar banco de dados</h2>\n        <p style='color: #7f1d1d;'><strong>Mensagem:</strong> \" . htmlspecialchars($e->getMessage()) . \"</p>\n        <p style='color: #7f1d1d;'><strong>Verifique:</strong></p>\n        <ul style='color: #7f1d1d;'>\n            <li>Se o MySQL está rodando</li>\n            <li>Suas credenciais em config.php</li>\n            <li>Se o usuário MySQL tem permissão para criar bancos</li>\n        </ul>\n    </div>\";\n}\n\n?>\n